 15→#[derive(Debug)]
 16→pub enum HookResult {
 17→    /// Success: hook completed successfully.
 18→    Success,
 19→    /// FailedContinue: hook failed, but other subsequent hooks should still execute and the
 20→    /// operation should continue.
 21→    FailedContinue(Box<dyn std::error::Error + Send + Sync + 'static>),
 22→    /// FailedAbort: hook failed, other subsequent hooks should not execute, and the operation
 23→    /// should be aborted.
 24→    FailedAbort(Box<dyn std::error::Error + Send + Sync + 'static>),
