 46→pub(crate) fn preview(
 47→    handlers: &[ConfiguredHandler],
 48→    _request: &UserPromptSubmitRequest,
 49→) -> Vec<HookRunSummary> {
 50→    dispatcher::select_handlers(
 51→        handlers,
 52→        HookEventName::UserPromptSubmit,
 53→        /*matcher_input*/ None,
 54→    )
 55→    .into_iter()
 56→    .map(|handler| dispatcher::running_summary(&handler))
 57→    .collect()
 58→}
