 60→pub(crate) async fn run(
 61→    handlers: &[ConfiguredHandler],
 62→    shell: &CommandShell,
 63→    request: UserPromptSubmitRequest,
 64→) -> UserPromptSubmitOutcome {
 65→    let matched = dispatcher::select_handlers(
 66→        handlers,
 67→        HookEventName::UserPromptSubmit,
 68→        /*matcher_input*/ None,
 69→    );
 70→    if matched.is_empty() {
 71→        return UserPromptSubmitOutcome {
 72→            hook_events: Vec::new(),
 73→            should_stop: false,
 74→            stop_reason: None,
 75→            additional_contexts: Vec::new(),
 76→        };
 77→    }
 78→
 79→    let input_json = match serde_json::to_string(&UserPromptSubmitCommandInput {
 80→        session_id: request.session_id.to_string(),
 81→        turn_id: request.turn_id.clone(),
 82→        transcript_path: NullableString::from_path(request.transcript_path.clone()),
 83→        cwd: request.cwd.display().to_string(),
 84→        hook_event_name: "UserPromptSubmit".to_string(),
 85→        model: request.model.clone(),
 86→        permission_mode: request.permission_mode.clone(),
 87→        prompt: request.prompt.clone(),
 88→    }) {
 89→        Ok(input_json) => input_json,
 90→        Err(error) => {
 91→            return serialization_failure_outcome(common::serialization_failure_hook_events(
 92→                matched,
 93→                Some(request.turn_id),
 94→                format!("failed to serialize user prompt submit hook input: {error}"),
 95→            ));
 96→        }
 97→    };
 98→
 99→    let results = dispatcher::execute_handlers(
100→        shell,
101→        matched,
102→        input_json,
103→        request.cwd.as_path(),
104→        Some(request.turn_id),
105→        parse_completed,
106→    )
107→    .await;
108→
109→    let should_stop = results.iter().any(|result| result.data.should_stop);
110→    let stop_reason = results
111→        .iter()
112→        .find_map(|result| result.data.stop_reason.clone());
113→    let additional_contexts = common::flatten_additional_contexts(
114→        results
115→            .iter()
116→            .map(|result| result.data.additional_contexts_for_model.as_slice()),
117→    );
118→
119→    UserPromptSubmitOutcome {
120→        hook_events: results.into_iter().map(|result| result.completed).collect(),
121→        should_stop,
122→        stop_reason,
123→        additional_contexts,
124→    }
125→}
