 88→        stop_hook_active: request.stop_hook_active,
 89→        last_assistant_message: NullableString::from_string(request.last_assistant_message.clone()),
 90→    }) {
 91→        Ok(input_json) => input_json,
 92→        Err(error) => {
 93→            return serialization_failure_outcome(common::serialization_failure_hook_events(
 94→                matched,
 95→                Some(request.turn_id),
 96→                format!("failed to serialize stop hook input: {error}"),
 97→            ));
 98→        }
 99→    };
100→
101→    let results = dispatcher::execute_handlers(
102→        shell,
103→        matched,
104→        input_json,
105→        request.cwd.as_path(),
106→        Some(request.turn_id),
107→        parse_completed,
108→    )
109→    .await;
110→
111→    let aggregate = aggregate_results(results.iter().map(|result| &result.data));
112→
113→    StopOutcome {
114→        hook_events: results.into_iter().map(|result| result.completed).collect(),
115→        should_stop: aggregate.should_stop,
116→        stop_reason: aggregate.stop_reason,
117→        should_block: aggregate.should_block,
118→        block_reason: aggregate.block_reason,
119→        continuation_fragments: aggregate.continuation_fragments,
120→    }
121→}
