123→fn parse_completed(
124→    handler: &ConfiguredHandler,
125→    run_result: CommandRunResult,
126→    turn_id: Option<String>,
127→) -> dispatcher::ParsedHandler<StopHandlerData> {
128→    let mut entries = Vec::new();
129→    let mut status = HookRunStatus::Completed;
130→    let mut should_stop = false;
131→    let mut stop_reason = None;
132→    let mut should_block = false;
133→    let mut block_reason = None;
134→    let mut continuation_prompt = None;
135→
136→    match run_result.error.as_deref() {
137→        Some(error) => {
138→            status = HookRunStatus::Failed;
139→            entries.push(HookOutputEntry {
140→                kind: HookOutputEntryKind::Error,
141→                text: error.to_string(),
142→            });
143→        }
144→        None => match run_result.exit_code {
145→            Some(0) => {
146→                let trimmed_stdout = run_result.stdout.trim();
147→                if trimmed_stdout.is_empty() {
148→                } else if let Some(parsed) = output_parser::parse_stop(&run_result.stdout) {
149→                    if let Some(system_message) = parsed.universal.system_message {
150→                        entries.push(HookOutputEntry {
151→                            kind: HookOutputEntryKind::Warning,
152→                            text: system_message,
153→                        });
154→                    }
155→                    let _ = parsed.universal.suppress_output;
156→                    if !parsed.universal.continue_processing {
157→                        status = HookRunStatus::Stopped;
158→                        should_stop = true;
159→                        stop_reason = parsed.universal.stop_reason.clone();
160→                        if let Some(stop_reason_text) = parsed.universal.stop_reason {
161→                            entries.push(HookOutputEntry {
162→                                kind: HookOutputEntryKind::Stop,
163→                                text: stop_reason_text,
164→                            });
165→                        }
166→                    } else if let Some(invalid_block_reason) = parsed.invalid_block_reason {
167→                        status = HookRunStatus::Failed;
168→                        entries.push(HookOutputEntry {
169→                            kind: HookOutputEntryKind::Error,
170→                            text: invalid_block_reason,
171→                        });
172→                    } else if parsed.should_block {
173→                        if let Some(reason) =
174→                            parsed.reason.as_deref().and_then(common::trimmed_non_empty)
175→                        {
176→                            status = HookRunStatus::Blocked;
177→                            should_block = true;
178→                            block_reason = Some(reason.clone());
179→                            continuation_prompt = Some(reason.clone());
180→                            entries.push(HookOutputEntry {
181→                                kind: HookOutputEntryKind::Feedback,
182→                                text: reason,
183→                            });
184→                        } else {
185→                            status = HookRunStatus::Failed;
186→                            entries.push(HookOutputEntry {
187→                                kind: HookOutputEntryKind::Error,
188→                                text:
189→                                    "Stop hook returned decision:block without a non-empty reason"
190→                                        .to_string(),
191→                            });
192→                        }
193→                    }
194→                } else {
195→                    status = HookRunStatus::Failed;
196→                    entries.push(HookOutputEntry {
197→                        kind: HookOutputEntryKind::Error,
198→                        text: "hook returned invalid stop hook JSON output".to_string(),
199→                    });
200→                }
201→            }
202→            Some(2) => {
203→                if let Some(reason) = common::trimmed_non_empty(&run_result.stderr) {
204→                    status = HookRunStatus::Blocked;
205→                    should_block = true;
206→                    block_reason = Some(reason.clone());
207→                    continuation_prompt = Some(reason.clone());
208→                    entries.push(HookOutputEntry {
209→                        kind: HookOutputEntryKind::Feedback,
210→                        text: reason,
211→                    });
212→                } else {
213→                    status = HookRunStatus::Failed;
214→                    entries.push(HookOutputEntry {
215→                        kind: HookOutputEntryKind::Error,
216→                        text:
217→                            "Stop hook exited with code 2 but did not write a continuation prompt to stderr"
218→                                .to_string(),
219→                    });
220→                }
221→            }
222→            Some(exit_code) => {
223→                status = HookRunStatus::Failed;
224→                entries.push(HookOutputEntry {
225→                    kind: HookOutputEntryKind::Error,
226→                    text: format!("hook exited with code {exit_code}"),
227→                });
228→            }
229→            None => {
230→                status = HookRunStatus::Failed;
231→                entries.push(HookOutputEntry {
232→                    kind: HookOutputEntryKind::Error,
233→                    text: "hook exited without a status code".to_string(),
234→                });
235→            }
236→        },
237→    }
238→
239→    let completed = HookCompletedEvent {
240→        turn_id,
241→        run: dispatcher::completed_summary(handler, &run_result, status, entries),
242→    };
243→    let continuation_fragments = continuation_prompt
244→        .map(|prompt| {
245→            vec![HookPromptFragment::from_single_hook(
246→                prompt,
247→                completed.run.id.clone(),
248→            )]
249→        })
250→        .unwrap_or_default();
251→
252→    dispatcher::ParsedHandler {
253→        completed,
254→        data: StopHandlerData {
255→            should_stop,
256→            stop_reason,
257→            should_block,
258→            block_reason,
259→            continuation_fragments,
260→        },
261→    }
262→}
263→
264→fn aggregate_results<'a>(
265→    results: impl IntoIterator<Item = &'a StopHandlerData>,
266→) -> StopHandlerData {
267→    let results = results.into_iter().collect::<Vec<_>>();
268→    let should_stop = results.iter().any(|result| result.should_stop);
269→    let stop_reason = results.iter().find_map(|result| result.stop_reason.clone());
270→    let should_block = !should_stop && results.iter().any(|result| result.should_block);
271→    let block_reason = if should_block {
272→        common::join_text_chunks(
273→            results
274→                .iter()
275→                .filter_map(|result| result.block_reason.clone())
276→                .collect(),
277→        )
278→    } else {
279→        None
280→    };
281→    let continuation_fragments = if should_block {
282→        results
283→            .iter()
284→            .filter(|result| result.should_block)
285→            .flat_map(|result| result.continuation_fragments.clone())
286→            .collect()
287→    } else {
288→        Vec::new()
289→    };
290→
291→    StopHandlerData {
292→        should_stop,
293→        stop_reason,
294→        should_block,
295→        block_reason,
296→        continuation_fragments,
297→    }
298→}
