103→fn build_command(shell: &CommandShell, handler: &ConfiguredHandler) -> Command {
104→    let mut command = if shell.program.is_empty() {
105→        default_shell_command()
106→    } else {
107→        Command::new(&shell.program)
108→    };
109→    if shell.program.is_empty() {
110→        command.arg(&handler.command);
111→        command
112→    } else {
113→        command.args(&shell.args);
114→        command.arg(&handler.command);
115→        command
116→    }
117→}
118→
119→fn default_shell_command() -> Command {
120→    #[cfg(windows)]
121→    {
122→        let comspec = std::env::var("COMSPEC").unwrap_or_else(|_| "cmd.exe".to_string());
123→        let mut command = Command::new(comspec);
124→        command.arg("/C");
125→        command
126→    }
127→
128→    #[cfg(not(windows))]
129→    {
130→        let shell = std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string());
131→        let mut command = Command::new(shell);
132→        command.arg("-lc");
133→        command
134→    }
135→}
