 87→fn build_skills_watcher(skills_manager: Arc<SkillsManager>) -> Arc<SkillsWatcher> {
 88→    if should_use_test_thread_manager_behavior()
 89→        && let Ok(handle) = Handle::try_current()
 90→        && handle.runtime_flavor() == RuntimeFlavor::CurrentThread
 91→    {
 92→        // The real watcher spins background tasks that can starve the
 93→        // current-thread test runtime and cause event waits to time out.
 94→        warn!("using noop skills watcher under current-thread test runtime");
 95→        return Arc::new(SkillsWatcher::noop());
 96→    }
 97→
 98→    let file_watcher = match FileWatcher::new() {
 99→        Ok(file_watcher) => Arc::new(file_watcher),
100→        Err(err) => {
101→            warn!("failed to initialize file watcher: {err}");
102→            Arc::new(FileWatcher::noop())
103→        }
104→    };
105→    let skills_watcher = Arc::new(SkillsWatcher::new(&file_watcher));
106→
107→    let mut rx = skills_watcher.subscribe();
108→    let skills_manager = Arc::clone(&skills_manager);
109→    if let Ok(handle) = Handle::try_current() {
110→        handle.spawn(async move {
111→            loop {
112→                match rx.recv().await {
113→                    Ok(SkillsWatcherEvent::SkillsChanged { .. }) => {
114→                        skills_manager.clear_cache();
115→                    }
116→                    Err(broadcast::error::RecvError::Closed) => break,
117→                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
118→                }
119→            }
120→        });
121→    } else {
122→        warn!("skills watcher listener skipped: no Tokio runtime available");
123→    }
124→
125→    skills_watcher
126→}
