137→    fn from_auth_dot_json(
138→        codex_home: &Path,
139→        auth_dot_json: AuthDotJson,
140→        auth_credentials_store_mode: AuthCredentialsStoreMode,
141→    ) -> std::io::Result<Self> {
142→        let auth_mode = auth_dot_json.resolved_mode();
143→        let client = create_client();
144→        if auth_mode == ApiAuthMode::ApiKey {
145→            let Some(api_key) = auth_dot_json.openai_api_key.as_deref() else {
146→                return Err(std::io::Error::other("API key auth is missing a key."));
147→            };
148→            return Ok(Self::from_api_key(api_key));
149→        }
150→
151→        let storage_mode = auth_dot_json.storage_mode(auth_credentials_store_mode);
152→        let state = ChatgptAuthState {
153→            auth_dot_json: Arc::new(Mutex::new(Some(auth_dot_json))),
154→            client,
155→        };
156→
157→        match auth_mode {
158→            ApiAuthMode::Chatgpt => {
159→                let storage = create_auth_storage(codex_home.to_path_buf(), storage_mode);
160→                Ok(Self::Chatgpt(ChatgptAuth { state, storage }))
161→            }
162→            ApiAuthMode::ChatgptAuthTokens => {
163→                Ok(Self::ChatgptAuthTokens(ChatgptAuthTokens { state }))
164→            }
165→            ApiAuthMode::ApiKey => unreachable!("api key mode is handled above"),
