285→    fn get_current_auth_json(&self) -> Option<AuthDotJson> {
286→        let state = match self {
287→            Self::Chatgpt(auth) => &auth.state,
288→            Self::ChatgptAuthTokens(auth) => &auth.state,
289→            Self::ApiKey(_) => return None,
290→        };
291→        #[expect(clippy::unwrap_used)]
