 63→pub(super) fn delete_file_if_exists(codex_home: &Path) -> std::io::Result<bool> {
 64→    let auth_file = get_auth_file(codex_home);
 65→    match std::fs::remove_file(&auth_file) {
 66→        Ok(()) => Ok(true),
