 72→pub(super) trait AuthStorageBackend: Debug + Send + Sync {
 73→    fn load(&self) -> std::io::Result<Option<AuthDotJson>>;
 74→    fn save(&self, auth: &AuthDotJson) -> std::io::Result<()>;
 75→    fn delete(&self) -> std::io::Result<bool>;
 76→}
