 78→#[derive(Clone, Debug)]
 79→pub(super) struct FileAuthStorage {
 80→    codex_home: PathBuf,
 81→}
 82→
 83→impl FileAuthStorage {
 84→    pub(super) fn new(codex_home: PathBuf) -> Self {
 85→        Self { codex_home }
 86→    }
 87→
 88→    /// Attempt to read and parse the `auth.json` file in the given `CODEX_HOME` directory.
 89→    /// Returns the full AuthDotJson structure.
 90→    pub(super) fn try_read_auth_json(&self, auth_file: &Path) -> std::io::Result<AuthDotJson> {
 91→        let mut file = File::open(auth_file)?;
 92→        let mut contents = String::new();
 93→        file.read_to_string(&mut contents)?;
 94→        let auth_dot_json: AuthDotJson = serde_json::from_str(&contents)?;
 95→
 96→        Ok(auth_dot_json)
 97→    }
 98→}
 99→
100→impl AuthStorageBackend for FileAuthStorage {
101→    fn load(&self) -> std::io::Result<Option<AuthDotJson>> {
102→        let auth_file = get_auth_file(&self.codex_home);
103→        let auth_dot_json = match self.try_read_auth_json(&auth_file) {
104→            Ok(auth) => auth,
105→            Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(None),
106→            Err(err) => return Err(err),
107→        };
108→        Ok(Some(auth_dot_json))
109→    }
110→
111→    fn save(&self, auth_dot_json: &AuthDotJson) -> std::io::Result<()> {
112→        let auth_file = get_auth_file(&self.codex_home);
113→
114→        if let Some(parent) = auth_file.parent() {
115→            std::fs::create_dir_all(parent)?;
116→        }
117→        let json_data = serde_json::to_string_pretty(auth_dot_json)?;
118→        let mut options = OpenOptions::new();
119→        options.truncate(true).write(true).create(true);
120→        #[cfg(unix)]
121→        {
122→            options.mode(0o600);
123→        }
124→        let mut file = options.open(auth_file)?;
125→        file.write_all(json_data.as_bytes())?;
126→        file.flush()?;
127→        Ok(())
128→    }
129→
130→    fn delete(&self) -> std::io::Result<bool> {
131→        delete_file_if_exists(&self.codex_home)
132→    }
133→}
