135→const KEYRING_SERVICE: &str = "Codex Auth";
136→
137→// turns codex_home path into a stable, short key string
138→fn compute_store_key(codex_home: &Path) -> std::io::Result<String> {
139→    let canonical = codex_home
140→        .canonicalize()
141→        .unwrap_or_else(|_| codex_home.to_path_buf());
142→    let path_str = canonical.to_string_lossy();
143→    let mut hasher = Sha256::new();
144→    hasher.update(path_str.as_bytes());
145→    let digest = hasher.finalize();
146→    let hex = format!("{digest:x}");
147→    let truncated = hex.get(..16).unwrap_or(&hex);
148→    Ok(format!("cli|{truncated}"))
149→}
150→
151→#[derive(Clone, Debug)]
152→struct KeyringAuthStorage {
153→    codex_home: PathBuf,
154→    keyring_store: Arc<dyn KeyringStore>,
155→}
156→
157→impl KeyringAuthStorage {
158→    fn new(codex_home: PathBuf, keyring_store: Arc<dyn KeyringStore>) -> Self {
159→        Self {
160→            codex_home,
161→            keyring_store,
162→        }
163→    }
164→
165→    fn load_from_keyring(&self, key: &str) -> std::io::Result<Option<AuthDotJson>> {
166→        match self.keyring_store.load(KEYRING_SERVICE, key) {
167→            Ok(Some(serialized)) => serde_json::from_str(&serialized).map(Some).map_err(|err| {
168→                std::io::Error::other(format!(
169→                    "failed to deserialize CLI auth from keyring: {err}"
170→                ))
171→            }),
172→            Ok(None) => Ok(None),
173→            Err(error) => Err(std::io::Error::other(format!(
174→                "failed to load CLI auth from keyring: {}",
175→                error.message()
176→            ))),
177→        }
178→    }
179→
180→    fn save_to_keyring(&self, key: &str, value: &str) -> std::io::Result<()> {
181→        match self.keyring_store.save(KEYRING_SERVICE, key, value) {
182→            Ok(()) => Ok(()),
183→            Err(error) => {
184→                let message = format!(
185→                    "failed to write OAuth tokens to keyring: {}",
186→                    error.message()
187→                );
188→                warn!("{message}");
189→                Err(std::io::Error::other(message))
190→            }
191→        }
192→    }
193→}
194→
195→impl AuthStorageBackend for KeyringAuthStorage {
196→    fn load(&self) -> std::io::Result<Option<AuthDotJson>> {
197→        let key = compute_store_key(&self.codex_home)?;
198→        self.load_from_keyring(&key)
199→    }
200→
201→    fn save(&self, auth: &AuthDotJson) -> std::io::Result<()> {
202→        let key = compute_store_key(&self.codex_home)?;
203→        // Simpler error mapping per style: prefer method reference over closure
204→        let serialized = serde_json::to_string(auth).map_err(std::io::Error::other)?;
205→        self.save_to_keyring(&key, &serialized)?;
206→        if let Err(err) = delete_file_if_exists(&self.codex_home) {
207→            warn!("failed to remove CLI auth fallback file: {err}");
208→        }
209→        Ok(())
210→    }
211→
212→    fn delete(&self) -> std::io::Result<bool> {
213→        let key = compute_store_key(&self.codex_home)?;
214→        let keyring_removed = self
215→            .keyring_store
216→            .delete(KEYRING_SERVICE, &key)
217→            .map_err(|err| {
218→                std::io::Error::other(format!("failed to delete auth from keyring: {err}"))
219→            })?;
220→        let file_removed = delete_file_if_exists(&self.codex_home)?;
221→        Ok(keyring_removed || file_removed)
222→    }
223→}
224→
225→#[derive(Clone, Debug)]
226→struct AutoAuthStorage {
227→    keyring_storage: Arc<KeyringAuthStorage>,
228→    file_storage: Arc<FileAuthStorage>,
229→}
230→
231→impl AutoAuthStorage {
232→    fn new(codex_home: PathBuf, keyring_store: Arc<dyn KeyringStore>) -> Self {
233→        Self {
234→            keyring_storage: Arc::new(KeyringAuthStorage::new(codex_home.clone(), keyring_store)),
235→            file_storage: Arc::new(FileAuthStorage::new(codex_home)),
236→        }
237→    }
238→}
239→
240→impl AuthStorageBackend for AutoAuthStorage {
241→    fn load(&self) -> std::io::Result<Option<AuthDotJson>> {
242→        match self.keyring_storage.load() {
243→            Ok(Some(auth)) => Ok(Some(auth)),
244→            Ok(None) => self.file_storage.load(),
245→            Err(err) => {
246→                warn!("failed to load CLI auth from keyring, falling back to file storage: {err}");
247→                self.file_storage.load()
248→            }
249→        }
250→    }

