107→fn print_login_server_start(actual_port: u16, auth_url: &str) {
108→    eprintln!(
109→        "Starting local login server on http://localhost:{actual_port}.\nIf your browser did not open, navigate to this URL to authenticate:\n\n{auth_url}\n\nOn a remote or headless machine? Use `codex login --device-auth` instead."
110→    );
