131→pub async fn run_login_with_chatgpt(cli_config_overrides: CliConfigOverrides) -> ! {
132→    let config = load_config_or_exit(cli_config_overrides).await;
133→    let _login_log_guard = init_login_file_logging(&config);
134→    tracing::info!("starting browser login flow");
135→
136→    if matches!(config.forced_login_method, Some(ForcedLoginMethod::Api)) {
137→        eprintln!("{CHATGPT_LOGIN_DISABLED_MESSAGE}");
138→        std::process::exit(1);
139→    }
140→
141→    let forced_chatgpt_workspace_id = config.forced_chatgpt_workspace_id.clone();
142→
143→    match login_with_chatgpt(
144→        config.codex_home,
145→        forced_chatgpt_workspace_id,
146→        config.cli_auth_credentials_store_mode,
147→    )
148→    .await
149→    {
150→        Ok(_) => {
151→            eprintln!("{LOGIN_SUCCESS_MESSAGE}");
152→            std::process::exit(0);
153→        }
154→        Err(e) => {
155→            eprintln!("Error logging in: {e}");
156→            std::process::exit(1);
157→        }
158→    }
159→}
