190→pub fn read_api_key_from_stdin() -> String {
191→    let mut stdin = std::io::stdin();
192→
193→    if stdin.is_terminal() {
194→        eprintln!(
195→            "--with-api-key expects the API key on stdin. Try piping it, e.g. `printenv OPENAI_API_KEY | codex login --with-api-key`."
196→        );
197→        std::process::exit(1);
198→    }
199→
200→    eprintln!("Reading API key from stdin...");
201→
202→    let mut buffer = String::new();
203→    if let Err(err) = stdin.read_to_string(&mut buffer) {
204→        eprintln!("Failed to read API key from stdin: {err}");
205→        std::process::exit(1);
206→    }
207→
208→    let api_key = buffer.trim().to_string();
209→    if api_key.is_empty() {
210→        eprintln!("No API key provided via stdin.");
211→        std::process::exit(1);
212→    }
213→
214→    api_key
215→}
