252→/// Prefers device-code login (with `open_browser = false`) when headless environment is detected, but keeps
253→/// `codex login` working in environments where device-code may be disabled/feature-gated.
254→/// If `run_device_code_login` returns `ErrorKind::NotFound` ("device-code unsupported"), this
255→/// falls back to starting the local browser login server.
256→pub async fn run_login_with_device_code_fallback_to_browser(
257→    cli_config_overrides: CliConfigOverrides,
258→    issuer_base_url: Option<String>,
259→    client_id: Option<String>,
260→) -> ! {
261→    let config = load_config_or_exit(cli_config_overrides).await;
262→    let _login_log_guard = init_login_file_logging(&config);
263→    tracing::info!("starting login flow with device code fallback");
264→    if matches!(config.forced_login_method, Some(ForcedLoginMethod::Api)) {
265→        eprintln!("{CHATGPT_LOGIN_DISABLED_MESSAGE}");
266→        std::process::exit(1);
267→    }
268→
269→    let forced_chatgpt_workspace_id = config.forced_chatgpt_workspace_id.clone();
270→    let mut opts = ServerOptions::new(
271→        config.codex_home,
272→        client_id.unwrap_or(CLIENT_ID.to_string()),
273→        forced_chatgpt_workspace_id,
274→        config.cli_auth_credentials_store_mode,
275→    );
276→    if let Some(iss) = issuer_base_url {
277→        opts.issuer = iss;
278→    }
279→    opts.open_browser = false;
280→
281→    match run_device_code_login(opts.clone()).await {
282→        Ok(()) => {
283→            eprintln!("{LOGIN_SUCCESS_MESSAGE}");
284→            std::process::exit(0);
285→        }
286→        Err(e) => {
287→            if e.kind() == std::io::ErrorKind::NotFound {
288→                eprintln!("Device code login is not enabled; falling back to browser login.");
289→                match run_login_server(opts) {
290→                    Ok(server) => {
291→                        print_login_server_start(server.actual_port, &server.auth_url);
292→                        match server.block_until_done().await {
293→                            Ok(()) => {
294→                                eprintln!("{LOGIN_SUCCESS_MESSAGE}");
295→                                std::process::exit(0);
296→                            }
297→                            Err(e) => {
298→                                eprintln!("Error logging in: {e}");
299→                                std::process::exit(1);
300→                            }

