 22→type CopilotCLI struct{}
 23→
 24→func (c *CopilotCLI) Name() string               { return "copilot-cli" }
 25→func (c *CopilotCLI) Binary() string             { return "copilot" }
 26→func (c *CopilotCLI) EntireAgent() string        { return "copilot-cli" }
