165→pub async fn run_main(cli: Cli, arg0_paths: Arg0DispatchPaths) -> anyhow::Result<()> {
166→    if let Err(err) = set_default_originator("codex_exec".to_string()) {
167→        tracing::warn!(?err, "Failed to set codex exec originator override {err:?}");
168→    }
169→
170→    let Cli {
171→        command,
172→        images,
173→        model: model_cli_arg,
174→        oss,
175→        oss_provider,
176→        config_profile,
177→        full_auto,
178→        dangerously_bypass_approvals_and_sandbox,
179→        cwd,
180→        skip_git_repo_check,
181→        add_dir,
182→        ephemeral,
183→        color,
184→        last_message_file,
185→        json: json_mode,
186→        sandbox_mode: sandbox_mode_cli_arg,
187→        prompt,
188→        output_schema: output_schema_path,
189→        config_overrides,
190→    } = cli;
191→
192→    let (_stdout_with_ansi, stderr_with_ansi) = match color {
193→        cli::Color::Always => (true, true),
194→        cli::Color::Never => (false, false),
195→        cli::Color::Auto => (
196→            supports_color::on_cached(Stream::Stdout).is_some(),
197→            supports_color::on_cached(Stream::Stderr).is_some(),
198→        ),
199→    };
200→    // Build fmt layer (existing logging) to compose with OTEL layer.
201→    let default_level = "error";
202→
203→    // Build env_filter separately and attach via with_filter.
204→    let env_filter = EnvFilter::try_from_default_env()
205→        .or_else(|_| EnvFilter::try_new(default_level))
206→        .unwrap_or_else(|_| EnvFilter::new(default_level));
207→
208→    let fmt_layer = tracing_subscriber::fmt::layer()
209→        .with_ansi(stderr_with_ansi)
210→        .with_writer(std::io::stderr)
211→        .with_filter(env_filter);
212→
213→    let sandbox_mode = if full_auto {
214→        Some(SandboxMode::WorkspaceWrite)
215→    } else if dangerously_bypass_approvals_and_sandbox {
216→        Some(SandboxMode::DangerFullAccess)
217→    } else {
218→        sandbox_mode_cli_arg.map(Into::<SandboxMode>::into)
219→    };
220→
221→    // Parse `-c` overrides from the CLI.
222→    let cli_kv_overrides = match config_overrides.parse_overrides() {
223→        Ok(v) => v,
224→        #[allow(clippy::print_stderr)]
225→        Err(e) => {
226→            eprintln!("Error parsing -c overrides: {e}");
227→            std::process::exit(1);
228→        }
229→    };
230→
231→    let resolved_cwd = cwd.clone();
232→    let config_cwd = match resolved_cwd.as_deref() {
233→        Some(path) => AbsolutePathBuf::from_absolute_path(path.canonicalize()?)?,
234→        None => AbsolutePathBuf::current_dir()?,
235→    };
236→
237→    // we load config.toml here to determine project state.
238→    #[allow(clippy::print_stderr)]
239→    let codex_home = match find_codex_home() {
240→        Ok(codex_home) => codex_home,
241→        Err(err) => {
242→            eprintln!("Error finding codex home: {err}");
243→            std::process::exit(1);
244→        }
245→    };
246→
