456→async fn run_exec_session(args: ExecRunArgs) -> anyhow::Result<()> {
457→    let ExecRunArgs {
458→        in_process_start_args,
459→        command,
460→        config,
461→        dangerously_bypass_approvals_and_sandbox,
462→        exec_span,
463→        images,
464→        json_mode,
465→        last_message_file,
466→        model_provider,
467→        oss,
468→        output_schema_path,
469→        prompt,
470→        skip_git_repo_check,
471→        stderr_with_ansi,
472→    } = args;
473→
474→    let mut event_processor: Box<dyn EventProcessor> = match json_mode {
475→        true => Box::new(EventProcessorWithJsonOutput::new(last_message_file.clone())),
476→        _ => Box::new(EventProcessorWithHumanOutput::create_with_ansi(
477→            stderr_with_ansi,
478→            &config,
479→            last_message_file.clone(),
480→        )),
481→    };
482→    if oss {
483→        // We're in the oss section, so provider_id should be Some
484→        // Let's handle None case gracefully though just in case
485→        let provider_id = match model_provider.as_ref() {
486→            Some(id) => id,
487→            None => {
488→                error!("OSS provider unexpectedly not set when oss flag is used");
489→                return Err(anyhow::anyhow!(
490→                    "OSS provider not set but oss flag was used"
491→                ));
492→            }
493→        };
494→        ensure_oss_provider_ready(provider_id, &config)
495→            .await
496→            .map_err(|e| anyhow::anyhow!("OSS setup failed: {e}"))?;
497→    }
498→
499→    let default_cwd = config.cwd.to_path_buf();
500→    let default_approval_policy = config.permissions.approval_policy.value();
501→    let default_sandbox_policy = config.permissions.sandbox_policy.get();
