508→        && get_git_repo_root(&default_cwd).is_none()
509→    {
510→        eprintln!("Not inside a trusted directory and --skip-git-repo-check was not specified.");
511→        std::process::exit(1);
512→    }
513→
514→    let mut request_ids = RequestIdSequencer::new();
515→    let mut client = InProcessAppServerClient::start(in_process_start_args)
516→        .await
517→        .map_err(|err| {
518→            anyhow::anyhow!("failed to initialize in-process app-server client: {err}")
519→        })?;
520→
521→    // Handle resume subcommand through existing `thread/list` + `thread/resume`
522→    // APIs so exec no longer reaches into rollout storage directly.
523→    let (primary_thread_id, fallback_session_configured) =
524→        if let Some(ExecCommand::Resume(args)) = command.as_ref() {
525→            if let Some(thread_id) = resolve_resume_thread_id(&client, &config, args).await? {
526→                let response: ThreadResumeResponse = send_request_with_response(
527→                    &client,
528→                    ClientRequest::ThreadResume {
529→                        request_id: request_ids.next(),
530→                        params: thread_resume_params_from_config(&config, thread_id),
531→                    },
532→                    "thread/resume",
533→                )
534→                .await
535→                .map_err(anyhow::Error::msg)?;
536→                let session_configured = session_configured_from_thread_resume_response(&response)
537→                    .map_err(anyhow::Error::msg)?;
538→                (session_configured.session_id, session_configured)
539→            } else {
