556→                &client,
557→                ClientRequest::ThreadStart {
558→                    request_id: request_ids.next(),
559→                    params: thread_start_params_from_config(&config),
560→                },
561→                "thread/start",
562→            )
563→            .await
564→            .map_err(anyhow::Error::msg)?;
565→            let session_configured = session_configured_from_thread_start_response(&response)
566→                .map_err(anyhow::Error::msg)?;
567→            (session_configured.session_id, session_configured)
