 94→        session_id: sess.conversation_id,
 95→        cwd: turn_context.cwd.clone(),
 96→        transcript_path: sess.hook_transcript_path().await,
 97→        model: turn_context.model_info.slug.clone(),
 98→        permission_mode: hook_permission_mode(turn_context),
 99→        source: session_start_source,
100→    };
101→    let preview_runs = sess.hooks().preview_session_start(&request);
102→    run_context_injecting_hook(
103→        sess,
104→        turn_context,
105→        preview_runs,
106→        sess.hooks()
107→            .run_session_start(request, Some(turn_context.sub_id.clone())),
108→    )
109→    .await
110→    .record_additional_contexts(sess, turn_context)
111→    .await
112→}
