900→/// The legacy mechanism for specifying admin-enforced configuration is to read
901→/// from a file like `/etc/codex/managed_config.toml` that has the same
902→/// structure as `config.toml` where fields like `approval_policy` can specify
903→/// exactly one value rather than a list of allowed values.
904→///
905→/// If present, re-interpret `managed_config.toml` as a `requirements.toml`
906→/// where each specified field is treated as a constraint allowing only that
907→/// value.
908→#[derive(Deserialize, Debug, Clone, Default, PartialEq)]
909→struct LegacyManagedConfigToml {
910→    approval_policy: Option<AskForApproval>,
911→    sandbox_mode: Option<SandboxMode>,
912→}
913→
914→impl From<LegacyManagedConfigToml> for ConfigRequirementsToml {
915→    fn from(legacy: LegacyManagedConfigToml) -> Self {
916→        let mut config_requirements_toml = ConfigRequirementsToml::default();
917→
918→        let LegacyManagedConfigToml {
919→            approval_policy,
920→            sandbox_mode,
921→        } = legacy;
922→        if let Some(approval_policy) = approval_policy {
923→            config_requirements_toml.allowed_approval_policies = Some(vec![approval_policy]);
924→        }
925→        if let Some(sandbox_mode) = sandbox_mode {
926→            let required_mode: SandboxModeRequirement = sandbox_mode.into();
927→            // Allowing read-only is a requirement for Codex to function correctly.
928→            // So in this backfill path, we append read-only if it's not already specified.
929→            let mut allowed_modes = vec![SandboxModeRequirement::ReadOnly];
930→            if required_mode != SandboxModeRequirement::ReadOnly {
931→                allowed_modes.push(required_mode);
932→            }
933→            config_requirements_toml.allowed_sandbox_modes = Some(allowed_modes);
934→        }
935→        config_requirements_toml
936→    }
937→}
