770→async fn find_project_root(
771→    cwd: &AbsolutePathBuf,
772→    project_root_markers: &[String],
773→) -> io::Result<AbsolutePathBuf> {
774→    if project_root_markers.is_empty() {
775→        return Ok(cwd.clone());
776→    }
777→
778→    for ancestor in cwd.as_path().ancestors() {
779→        for marker in project_root_markers {
780→            let marker_path = ancestor.join(marker);
781→            if tokio::fs::metadata(&marker_path).await.is_ok() {
782→                return AbsolutePathBuf::from_absolute_path(ancestor);
783→            }
784→        }
785→    }
786→    Ok(cwd.clone())
787→}
