603→        if let Some(trust_level) = self.projects_trust.get(&dir_key).copied() {
604→            return ProjectTrustDecision {
605→                trust_level: Some(trust_level),
606→                trust_key: dir_key,
607→            };
608→        }
609→
610→        if let Some(trust_level) = self.projects_trust.get(&self.project_root_key).copied() {
611→            return ProjectTrustDecision {
612→                trust_level: Some(trust_level),
613→                trust_key: self.project_root_key.clone(),
614→            };
615→        }
616→
617→        if let Some(repo_root_key) = self.repo_root_key.as_ref()
618→            && let Some(trust_level) = self.projects_trust.get(repo_root_key).copied()
619→        {
620→            return ProjectTrustDecision {
621→                trust_level: Some(trust_level),
622→                trust_key: repo_root_key.clone(),
623→            };
624→        }
625→
626→        ProjectTrustDecision {
627→            trust_level: None,
628→            trust_key: self
629→                .repo_root_key
630→                .clone()
631→                .unwrap_or_else(|| self.project_root_key.clone()),
