 56→// codexHome creates an isolated CODEX_HOME for a test run.
 57→// This keeps trust entries and feature flags out of the real ~/.codex/config.toml.
 58→// Auth still works via OPENAI_API_KEY env var (checked before CODEX_HOME).
 59→func codexHome() (string, func(), error) {
 60→	dir, err := os.MkdirTemp("", "codex-home-*")
 61→	if err != nil {
 62→		return "", nil, err
 63→	}
 64→	return dir, func() { _ = os.RemoveAll(dir) }, nil
 65→}
