 67→func (c *Codex) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 68→	cfg := &runConfig{}
 69→	for _, o := range opts {
 70→		o(cfg)
 71→	}
 72→
 73→	home, cleanup, err := codexHome()
 74→	if err != nil {
 75→		return Output{}, fmt.Errorf("create codex home: %w", err)
 76→	}
 77→	defer cleanup()
 78→
 79→	args := []string{
 80→		"exec",
 81→		"--dangerously-bypass-approvals-and-sandbox",
 82→	}
 83→	if cfg.Model != "" {
 84→		args = append(args, "-m", cfg.Model)
 85→	}
 86→	args = append(args, prompt)
 87→
 88→	displayArgs := []string{
 89→		"exec",
 90→		"--dangerously-bypass-approvals-and-sandbox",
 91→	}
 92→	if cfg.Model != "" {
 93→		displayArgs = append(displayArgs, "-m", cfg.Model)
 94→	}
 95→	displayArgs = append(displayArgs, fmt.Sprintf("%q", prompt))
 96→
 97→	env := append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME"),
 98→		"CODEX_HOME="+home,
 99→	)
100→
101→	// entire enable wrote trust + feature flag via CODEX_HOME during SetupRepo.
102→	// But SetupRepo's CODEX_HOME pointed at a different temp dir. We need to
103→	// re-seed trust for this isolated home so Codex loads .codex/hooks.json.
104→	absDir, _ := filepath.Abs(dir)
105→	if err := seedCodexHome(home, absDir); err != nil {
106→		return Output{}, fmt.Errorf("seed codex home: %w", err)
107→	}
108→
109→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
110→	cmd.Dir = dir
111→	cmd.Stdin = nil
112→	cmd.Env = env
113→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
114→	cmd.Cancel = func() error {
115→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
116→	}
117→	cmd.WaitDelay = 5 * time.Second
118→
119→	var stdout, stderr strings.Builder
120→	cmd.Stdout = &stdout
121→	cmd.Stderr = &stderr
122→
123→	err = cmd.Run()
124→	exitCode := 0
125→	if err != nil {
126→		exitErr := &exec.ExitError{}
127→		if errors.As(err, &exitErr) {
128→			exitCode = exitErr.ExitCode()
129→		} else {
130→			exitCode = -1
131→		}
132→	}
133→
134→	return Output{
135→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
136→		Stdout:   stdout.String(),
137→		Stderr:   stderr.String(),
138→		ExitCode: exitCode,
139→	}, err
140→}
141→
142→func (c *Codex) StartSession(ctx context.Context, dir string) (Session, error) {
143→	name := fmt.Sprintf("codex-test-%d", time.Now().UnixNano())
144→
145→	home, cleanup, err := codexHome()
146→	if err != nil {
147→		return nil, fmt.Errorf("create codex home: %w", err)
148→	}
149→
150→	absDir, _ := filepath.Abs(dir)
151→	if err := seedCodexHome(home, absDir); err != nil {
152→		cleanup()
153→		return nil, fmt.Errorf("seed codex home: %w", err)
154→	}
155→
156→	env := filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME")
157→
158→	s, err := NewTmuxSession(name, dir, nil, "env",
159→		"CODEX_HOME="+home,
160→		"codex", "--dangerously-bypass-approvals-and-sandbox",
161→	)
162→	if err != nil {
163→		cleanup()
164→		return nil, err
165→	}
166→	s.OnClose(cleanup)
167→
168→	// Forward API key if present
169→	for _, e := range env {
170→		if strings.HasPrefix(e, "OPENAI_API_KEY=") {
171→			_ = s.Send("export " + e)
172→		}
173→	}
174→
175→	// Dismiss startup dialogs (model upgrade prompts, etc.) until we reach
176→	// the input prompt. Similar to Claude's startup dialog handling.
177→	for range 5 {
178→		content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
179→		if waitErr != nil {
180→			_ = s.Close()
181→			return nil, fmt.Errorf("waiting for codex prompt: %w", waitErr)
182→		}
183→		if !strings.Contains(content, "press enter to confirm") &&
184→			!strings.Contains(content, "Use ↑/↓ to move") {
185→			break
186→		}
187→		_ = s.SendKeys("Enter")
188→		time.Sleep(500 * time.Millisecond)
189→	}
190→
191→	return s, nil
192→}
193→
194→// seedCodexHome writes trust + feature flag config and links auth credentials
195→// so Codex loads the project's .codex/ layer and can authenticate.
196→func seedCodexHome(home, projectDir string) error {
197→	if err := os.MkdirAll(home, 0o750); err != nil {
198→		return err
199→	}
200→
201→	// Write config with trust, feature flag, and pinned model to skip upgrade dialogs
202→	config := fmt.Sprintf("model = \"gpt-5.4\"\n\n[features]\ncodex_hooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", projectDir)
203→	if err := os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600); err != nil {
204→		return err
205→	}
206→
207→	// Symlink auth.json from the real ~/.codex/ so API credentials are available.
208→	// Auth via OPENAI_API_KEY env var still works, but codex may also check auth.json
209→	// for OAuth/token-based auth.
210→	if realHome, err := os.UserHomeDir(); err == nil {
211→		src := filepath.Join(realHome, ".codex", "auth.json")
212→		if _, err := os.Stat(src); err == nil {
213→			_ = os.Symlink(src, filepath.Join(home, "auth.json"))
214→		}
215→	}
216→
217→	return nil
218→}
