194→// seedCodexHome writes trust + feature flag config and links auth credentials
195→// so Codex loads the project's .codex/ layer and can authenticate.
196→func seedCodexHome(home, projectDir string) error {
197→	if err := os.MkdirAll(home, 0o750); err != nil {
198→		return err
199→	}
200→
201→	// Write config with trust, feature flag, and pinned model to skip upgrade dialogs
202→	config := fmt.Sprintf("model = \"gpt-5.4\"\n\n[features]\ncodex_hooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", projectDir)
203→	if err := os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600); err != nil {
204→		return err
205→	}
206→
207→	// Symlink auth.json from the real ~/.codex/ so API credentials are available.
208→	// Auth via OPENAI_API_KEY env var still works, but codex may also check auth.json
209→	// for OAuth/token-based auth.
210→	if realHome, err := os.UserHomeDir(); err == nil {
211→		src := filepath.Join(realHome, ".codex", "auth.json")
212→		if _, err := os.Stat(src); err == nil {
213→			_ = os.Symlink(src, filepath.Join(home, "auth.json"))
214→		}
215→	}
216→
217→	return nil
218→}
