 22→}
 23→
 24→// InstallHooks installs Codex hooks in .codex/hooks.json.
 25→func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 26→	repoRoot, err := paths.WorktreeRoot(ctx)
 27→	if err != nil {
 28→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
 29→		if err != nil {
 30→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 31→		}
 32→	}
 33→
 34→	hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
 35→
 36→	// Read existing hooks.json if present
 37→	var rawHooks map[string]json.RawMessage
 38→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
 39→	if readErr == nil {
 40→		var hooksFile map[string]json.RawMessage
 41→		if err := json.Unmarshal(existingData, &hooksFile); err != nil {
 42→			return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
 43→		}
 44→		if hooksRaw, ok := hooksFile["hooks"]; ok {
 45→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 46→				return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
 47→			}
 48→		}
 49→	}
 50→
 51→	if rawHooks == nil {
 52→		rawHooks = make(map[string]json.RawMessage)
 53→	}
 54→
 55→	// Parse event types we manage
 56→	var sessionStart, userPromptSubmit, stop []MatcherGroup
 57→	parseHookType(rawHooks, "SessionStart", &sessionStart)
 58→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
 59→	parseHookType(rawHooks, "Stop", &stop)
 60→
 61→	if force {
 62→		sessionStart = removeEntireHooks(sessionStart)
 63→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
 64→		stop = removeEntireHooks(stop)
 65→	}
 66→
 67→	// Build hook commands
 68→	var sessionStartCmd, userPromptSubmitCmd, stopCmd string
 69→	if localDev {
 70→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex session-start"
 71→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex user-prompt-submit"
 72→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex stop"
 73→	} else {
 74→		sessionStartCmd = "entire hooks codex session-start"
 75→		userPromptSubmitCmd = "entire hooks codex user-prompt-submit"
 76→		stopCmd = "entire hooks codex stop"
 77→	}
 78→
 79→	count := 0
 80→
 81→	if !hookCommandExists(sessionStart, sessionStartCmd) {
 82→		sessionStart = addHook(sessionStart, sessionStartCmd)
 83→		count++
 84→	}
 85→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
 86→		userPromptSubmit = addHook(userPromptSubmit, userPromptSubmitCmd)
 87→		count++
 88→	}
 89→	if !hookCommandExists(stop, stopCmd) {
 90→		stop = addHook(stop, stopCmd)
 91→		count++
 92→	}
 93→
 94→	if count == 0 {
 95→		return 0, nil
 96→	}
 97→
 98→	// Marshal modified types back
 99→	marshalHookType(rawHooks, "SessionStart", sessionStart)
100→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
101→	marshalHookType(rawHooks, "Stop", stop)
102→
103→	// Build the top-level structure
104→	topLevel := map[string]json.RawMessage{}
105→	hooksJSON, err := json.Marshal(rawHooks)
106→	if err != nil {
107→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
108→	}
109→	topLevel["hooks"] = hooksJSON
110→
111→	// Write to file
112→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
113→		return 0, fmt.Errorf("failed to create .codex directory: %w", err)
114→	}
115→
116→	output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
117→	if err != nil {
118→		return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
119→	}
120→
121→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
122→		return 0, fmt.Errorf("failed to write hooks.json: %w", err)
123→	}
124→
125→	// Enable the codex_hooks feature in the project-level .codex/config.toml.
126→	// This keeps the feature flag per-repo rather than global.
127→	if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
128→		return count, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
129→	}
130→
131→	// Trust this project in the user-level ~/.codex/config.toml so Codex
132→	// actually loads the project-level .codex/ config layer (hooks.json + config.toml).
133→	// Without trust, Codex silently disables the entire project layer.
134→	if err := ensureProjectTrusted(repoRoot); err != nil {
135→		return count, fmt.Errorf("failed to trust project: %w", err)
136→	}
137→
138→	return count, nil
139→}
