141→// UninstallHooks removes Entire hooks from Codex hooks.json.
142→func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
143→	repoRoot, err := paths.WorktreeRoot(ctx)
144→	if err != nil {
145→		repoRoot = "."
146→	}
147→
148→	hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
149→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
150→	if err != nil {
151→		return nil //nolint:nilerr // No hooks.json means nothing to uninstall
152→	}
153→
154→	var topLevel map[string]json.RawMessage
155→	if err := json.Unmarshal(data, &topLevel); err != nil {
156→		return fmt.Errorf("failed to parse hooks.json: %w", err)
157→	}
158→
159→	var rawHooks map[string]json.RawMessage
160→	if hooksRaw, ok := topLevel["hooks"]; ok {
161→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
162→			return fmt.Errorf("failed to parse hooks: %w", err)
163→		}
164→	}
165→	if rawHooks == nil {
166→		return nil
167→	}
168→
169→	var sessionStart, userPromptSubmit, stop []MatcherGroup
170→	parseHookType(rawHooks, "SessionStart", &sessionStart)
171→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
172→	parseHookType(rawHooks, "Stop", &stop)
173→
174→	sessionStart = removeEntireHooks(sessionStart)
175→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
176→	stop = removeEntireHooks(stop)
177→
178→	marshalHookType(rawHooks, "SessionStart", sessionStart)
179→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
180→	marshalHookType(rawHooks, "Stop", stop)
181→
182→	if len(rawHooks) > 0 {
183→		hooksJSON, err := json.Marshal(rawHooks)
184→		if err != nil {
185→			return fmt.Errorf("failed to marshal hooks: %w", err)
186→		}
187→		topLevel["hooks"] = hooksJSON
188→	} else {
189→		delete(topLevel, "hooks")
190→	}
191→
192→	output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
193→	if err != nil {
194→		return fmt.Errorf("failed to marshal hooks.json: %w", err)
195→	}
196→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
197→		return fmt.Errorf("failed to write hooks.json: %w", err)
198→	}
199→	return nil
200→}
