224→// --- Helpers ---
225→
226→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) {
227→	if data, ok := rawHooks[hookType]; ok {
228→		//nolint:errcheck,gosec // Intentionally ignoring parse errors
229→		json.Unmarshal(data, target)
230→	}
231→}
232→
233→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
234→	if len(groups) == 0 {
235→		delete(rawHooks, hookType)
236→		return
237→	}
238→	data, err := json.Marshal(groups)
239→	if err != nil {
240→		return
241→	}
242→	rawHooks[hookType] = data
243→}
244→
245→func hookCommandExists(groups []MatcherGroup, command string) bool {
246→	for _, group := range groups {
247→		for _, hook := range group.Hooks {
248→			if hook.Command == command {
249→				return true
250→			}
251→		}
252→	}
253→	return false
254→}
255→
256→func addHook(groups []MatcherGroup, command string) []MatcherGroup {
257→	entry := HookEntry{
258→		Type:    "command",
259→		Command: command,
260→		Timeout: 30,
261→	}
262→
263→	// Add to an existing group with null matcher, or create a new one
264→	for i, group := range groups {
265→		if group.Matcher == nil {
266→			groups[i].Hooks = append(groups[i].Hooks, entry)
267→			return groups
268→		}
269→	}
270→	return append(groups, MatcherGroup{
271→		Matcher: nil,
272→		Hooks:   []HookEntry{entry},
273→	})
274→}
275→
276→func isEntireHook(command string) bool {
277→	for _, prefix := range entireHookPrefixes {
278→		if strings.HasPrefix(command, prefix) {
279→			return true
280→		}
281→	}
282→	return false
283→}
284→
285→func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
286→	result := make([]MatcherGroup, 0, len(groups))
287→	for _, group := range groups {
288→		filtered := make([]HookEntry, 0, len(group.Hooks))
289→		for _, hook := range group.Hooks {
290→			if !isEntireHook(hook.Command) {
291→				filtered = append(filtered, hook)
292→			}
293→		}
294→		if len(filtered) > 0 {
295→			group.Hooks = filtered
296→			result = append(result, group)
297→		}
298→	}
299→	return result
300→}
