302→// configFileName is the Codex config file name.
303→const configFileName = "config.toml"
304→
305→// featureLine is the TOML line that enables the codex_hooks feature.
306→const featureLine = "codex_hooks = true"
307→
308→// ensureProjectFeatureEnabled writes features.codex_hooks = true to the
309→// project-level .codex/config.toml. This keeps the feature flag per-repo.
310→func ensureProjectFeatureEnabled(repoRoot string) error {
311→	configPath := filepath.Join(repoRoot, ".codex", configFileName)
312→
313→	data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
314→	if err != nil && !os.IsNotExist(err) {
315→		return fmt.Errorf("failed to read config.toml: %w", err)
316→	}
317→
318→	content := string(data)
319→	if strings.Contains(content, featureLine) {
320→		return nil
321→	}
322→
323→	if strings.Contains(content, "[features]") {
324→		content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
325→	} else {
326→		if len(content) > 0 && !strings.HasSuffix(content, "\n") {
327→			content += "\n"
328→		}
329→		content += "\n[features]\n" + featureLine + "\n"
330→	}
331→
332→	if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
333→		return fmt.Errorf("failed to create .codex directory: %w", err)
334→	}
335→	if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
336→		return fmt.Errorf("failed to write config.toml: %w", err)
337→	}
338→	return nil
339→}
340→
341→// ensureProjectTrusted adds a trust entry for the repo in the user-level
342→// ~/.codex/config.toml so Codex loads the project's .codex/ config layer.
343→func ensureProjectTrusted(repoRoot string) error {
344→	codexHome := os.Getenv("CODEX_HOME")
345→	if codexHome == "" {
346→		homeDir, err := os.UserHomeDir()
347→		if err != nil {
348→			return fmt.Errorf("failed to get home directory: %w", err)
349→		}
350→		codexHome = filepath.Join(homeDir, ".codex")
351→	}
352→
353→	absRoot, err := filepath.Abs(repoRoot)
354→	if err != nil {
355→		return fmt.Errorf("failed to resolve absolute path: %w", err)
356→	}
357→
358→	configPath := filepath.Join(codexHome, configFileName)
359→
360→	data, err := os.ReadFile(configPath) //nolint:gosec // path in user home directory
361→	if err != nil && !os.IsNotExist(err) {
362→		return fmt.Errorf("failed to read config.toml: %w", err)
363→	}
364→
365→	content := string(data)
366→
367→	trustSection := fmt.Sprintf("[projects.%q]", absRoot)
368→	if strings.Contains(content, trustSection) {
369→		return nil // already has an entry for this project
370→	}
371→
372→	if len(content) > 0 && !strings.HasSuffix(content, "\n") {
373→		content += "\n"
374→	}
375→	content += "\n" + trustSection + "\n" + `trust_level = "trusted"` + "\n"
376→
377→	if err := os.MkdirAll(codexHome, 0o750); err != nil { //nolint:gosec // path from CODEX_HOME env or user home directory
378→		return fmt.Errorf("failed to create codex home directory: %w", err)
379→	}
380→	if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path in user home directory
381→		return fmt.Errorf("failed to write config.toml: %w", err)
382→	}
383→	return nil
384→}
