202→// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
203→func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
204→	repoRoot, err := paths.WorktreeRoot(ctx)
205→	if err != nil {
206→		repoRoot = "."
207→	}
208→
209→	hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
210→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
211→	if err != nil {
212→		return false
213→	}
214→
215→	var hooksFile HooksFile
216→	if err := json.Unmarshal(data, &hooksFile); err != nil {
217→		return false
218→	}
219→
220→	return hookCommandExists(hooksFile.Hooks.Stop, "entire hooks codex stop") ||
221→		hookCommandExists(hooksFile.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks codex stop")
222→}
