 21→// WriteHookResponse outputs a JSON hook response to stdout.
 22→// Gemini CLI reads this JSON and displays the systemMessage to the user.
 23→func (g *GeminiCLIAgent) WriteHookResponse(message string) error {
 24→	resp := struct {
 25→		SystemMessage string `json:"systemMessage,omitempty"`
 26→	}{SystemMessage: message}
 27→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
 28→		return fmt.Errorf("failed to encode hook response: %w", err)
 29→	}
 30→	return nil
 31→}
