 33→// HookNames returns the hook verbs Gemini CLI supports.
 34→// These become subcommands: entire hooks gemini <verb>
 35→func (g *GeminiCLIAgent) HookNames() []string {
 36→	return []string{
 37→		HookNameSessionStart,
 38→		HookNameSessionEnd,
 39→		HookNameBeforeAgent,
 40→		HookNameAfterAgent,
 41→		HookNameBeforeModel,
 42→		HookNameAfterModel,
 43→		HookNameBeforeToolSelection,
 44→		HookNameBeforeTool,
 45→		HookNameAfterTool,
 46→		HookNamePreCompress,
 47→		HookNameNotification,
 48→	}
 49→}
 50→
 51→// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
 52→// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
 53→func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 54→	switch hookName {
 55→	case HookNameSessionStart:
 56→		return g.parseSessionStart(stdin)
 57→	case HookNameBeforeAgent:
 58→		return g.parseTurnStart(stdin)
 59→	case HookNameAfterAgent:
 60→		return g.parseTurnEnd(stdin)
 61→	case HookNameSessionEnd:
 62→		return g.parseSessionEnd(stdin)
 63→	case HookNamePreCompress:
 64→		return g.parseCompaction(stdin)
 65→	case HookNameBeforeModel:
 66→		return g.parseBeforeModel(stdin)
 67→	case HookNameBeforeTool, HookNameAfterTool,
 68→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 69→		// Acknowledged hooks with no lifecycle action
 70→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 71→	default:
 72→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 73→	}
 74→}
