 76→// ReadTranscript reads the raw JSON transcript bytes for a session.
 77→func (g *GeminiCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 78→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 79→	if err != nil {
 80→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 81→	}
 82→	return data, nil
 83→}
