 85→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
 86→func GetAgentsWithHooksInstalled(ctx context.Context) []types.AgentName {
 87→	var installed []types.AgentName
 88→	for _, name := range agent.List() {
 89→		ag, err := agent.Get(name)
 90→		if err != nil {
 91→			continue
 92→		}
 93→		if hs, ok := agent.AsHookSupport(ag); ok && hs.AreHooksInstalled(ctx) {
 94→			installed = append(installed, name)
 95→		}
 96→	}
 97→	return installed
 98→}
