  1→package claudecode
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"io"
  8→	"log/slog"
  9→	"os"
 10→	"strings"
 11→	"time"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/logging"
 15→)
 16→
 17→// Compile-time interface assertions for new interfaces.
 18→var (
 19→	_ agent.TranscriptAnalyzer     = (*ClaudeCodeAgent)(nil)
 20→	_ agent.TranscriptPreparer     = (*ClaudeCodeAgent)(nil)
 21→	_ agent.TokenCalculator        = (*ClaudeCodeAgent)(nil)
 22→	_ agent.SubagentAwareExtractor = (*ClaudeCodeAgent)(nil)
 23→	_ agent.HookResponseWriter     = (*ClaudeCodeAgent)(nil)
 24→)
 25→
 26→// WriteHookResponse outputs a JSON hook response to stdout.
 27→// Claude Code reads this JSON and displays the systemMessage to the user.
 28→func (c *ClaudeCodeAgent) WriteHookResponse(message string) error {
 29→	resp := struct {
 30→		SystemMessage string `json:"systemMessage,omitempty"`
 31→	}{SystemMessage: message}
 32→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
 33→		return fmt.Errorf("failed to encode hook response: %w", err)
 34→	}
 35→	return nil
 36→}
 37→
 38→// HookNames returns the hook verbs Claude Code supports.
 39→// These become subcommands: entire hooks claude-code <verb>
 40→func (c *ClaudeCodeAgent) HookNames() []string {
 41→	return []string{
 42→		HookNameSessionStart,
 43→		HookNameSessionEnd,
 44→		HookNameStop,
 45→		HookNameUserPromptSubmit,
 46→		HookNamePreTask,
 47→		HookNamePostTask,
 48→		HookNamePostTodo,
 49→	}
 50→}
 51→
 52→// ParseHookEvent translates a Claude Code hook into a normalized lifecycle Event.
 53→// Returns nil if the hook has no lifecycle significance.
 54→func (c *ClaudeCodeAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 55→	switch hookName {
 56→	case HookNameSessionStart:
 57→		return c.parseSessionStart(stdin)
 58→	case HookNameUserPromptSubmit:
 59→		return c.parseTurnStart(stdin)
 60→	case HookNameStop:
 61→		return c.parseTurnEnd(stdin)
 62→	case HookNameSessionEnd:
 63→		return c.parseSessionEnd(stdin)
 64→	case HookNamePreTask:
 65→		return c.parseSubagentStart(stdin)
 66→	case HookNamePostTask:
 67→		return c.parseSubagentEnd(stdin)
 68→	case HookNamePostTodo:
 69→		// PostTodo is Claude-specific; handled outside the generic dispatcher.
 70→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 71→	default:
 72→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 73→	}
 74→}
 75→
 76→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 77→func (c *ClaudeCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 78→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 79→	if err != nil {
 80→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 81→	}
 82→	return data, nil
 83→}
 84→
 85→// PrepareTranscript waits for Claude Code's async transcript flush to complete.
 86→// Claude writes a hook_progress sentinel entry after flushing all pending writes.
 87→func (c *ClaudeCodeAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
 88→	waitForTranscriptFlush(ctx, sessionRef, time.Now())
 89→	return nil
 90→}
 91→
 92→// CalculateTokenUsage computes token usage from the transcript starting at the given line offset.
 93→func (c *ClaudeCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
 94→	return c.CalculateTotalTokenUsage(transcriptData, fromOffset, "")
 95→}
 96→
 97→// --- Internal hook parsing functions ---
 98→
 99→func (c *ClaudeCodeAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
100→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
101→	if err != nil {
102→		return nil, err
103→	}
104→	return &agent.Event{
105→		Type:       agent.SessionStart,
106→		SessionID:  raw.SessionID,
107→		SessionRef: raw.TranscriptPath,
108→		Model:      raw.Model,
109→		Timestamp:  time.Now(),
110→	}, nil
111→}
112→
113→func (c *ClaudeCodeAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
114→	raw, err := agent.ReadAndParseHookInput[userPromptSubmitRaw](stdin)
115→	if err != nil {
116→		return nil, err
117→	}
118→	return &agent.Event{
119→		Type:       agent.TurnStart,
120→		SessionID:  raw.SessionID,
121→		SessionRef: raw.TranscriptPath,
122→		Prompt:     raw.Prompt,
123→		Timestamp:  time.Now(),
124→	}, nil
125→}
126→
127→func (c *ClaudeCodeAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
128→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
129→	if err != nil {
130→		return nil, err
131→	}
132→	return &agent.Event{
133→		Type:       agent.TurnEnd,
134→		SessionID:  raw.SessionID,
135→		SessionRef: raw.TranscriptPath,
136→		Timestamp:  time.Now(),
137→	}, nil
138→}
139→
140→func (c *ClaudeCodeAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
141→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
142→	if err != nil {
143→		return nil, err
144→	}
145→	return &agent.Event{
146→		Type:       agent.SessionEnd,
147→		SessionID:  raw.SessionID,
148→		SessionRef: raw.TranscriptPath,
149→		Timestamp:  time.Now(),
150→	}, nil
151→}
152→
153→func (c *ClaudeCodeAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
154→	raw, err := agent.ReadAndParseHookInput[taskHookInputRaw](stdin)
155→	if err != nil {
156→		return nil, err
157→	}
158→	return &agent.Event{
159→		Type:       agent.SubagentStart,
160→		SessionID:  raw.SessionID,
161→		SessionRef: raw.TranscriptPath,
162→		ToolUseID:  raw.ToolUseID,
163→		ToolInput:  raw.ToolInput,
164→		Timestamp:  time.Now(),
165→	}, nil
166→}
167→
168→func (c *ClaudeCodeAgent) parseSubagentEnd(stdin io.Reader) (*agent.Event, error) {
169→	raw, err := agent.ReadAndParseHookInput[postToolHookInputRaw](stdin)
170→	if err != nil {
171→		return nil, err
172→	}
173→	event := &agent.Event{
174→		Type:       agent.SubagentEnd,
175→		SessionID:  raw.SessionID,
176→		SessionRef: raw.TranscriptPath,
177→		ToolUseID:  raw.ToolUseID,
178→		ToolInput:  raw.ToolInput,
179→		Timestamp:  time.Now(),
180→	}
181→	if raw.ToolResponse.AgentID != "" {
182→		event.SubagentID = raw.ToolResponse.AgentID
183→	}
184→	return event, nil
185→}
186→
187→// --- Transcript flush sentinel ---
188→
189→// stopHookSentinel is the string that appears in Claude Code's hook_progress
190→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
191→const stopHookSentinel = "hooks claude-code stop"
192→
193→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
194→// Falls back silently after a timeout.
195→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
196→	const (
197→		maxWait      = 3 * time.Second
198→		pollInterval = 50 * time.Millisecond
199→		tailBytes    = 4096
200→		maxSkew      = 2 * time.Second
201→	)
202→
203→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
204→
205→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
206→	// - File doesn't exist: nothing to poll.
207→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
208→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
209→	//   without firing stop hook).
210→	const staleThreshold = 2 * time.Minute
211→	info, err := os.Stat(transcriptPath)
212→	if err != nil {
213→		// Most likely the file doesn't exist; other errors (permission, etc.)
214→		// would also prevent polling, so skip the wait either way.
215→		return
216→	}
217→	fileAge := time.Since(info.ModTime())
218→	if fileAge > staleThreshold {
219→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
220→			slog.Duration("file_age", fileAge),
221→		)
222→		return
223→	}
224→
225→	deadline := time.Now().Add(maxWait)
226→	for time.Now().Before(deadline) {
227→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
228→			logging.Debug(logCtx, "transcript flush sentinel found",
229→				slog.Duration("wait", time.Since(hookStartTime)),
230→			)
231→			return
232→		}
233→		time.Sleep(pollInterval)
234→	}
235→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
236→		slog.Duration("timeout", maxWait),
237→	)
238→}
239→
240→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
241→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
242→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
243→	if err != nil {
244→		return false
245→	}
246→	defer f.Close()
247→
248→	info, err := f.Stat()
249→	if err != nil {
250→		return false
251→	}
252→	offset := info.Size() - tailBytes
253→	if offset < 0 {
254→		offset = 0
255→	}
256→	buf := make([]byte, info.Size()-offset)
257→	if _, err := f.ReadAt(buf, offset); err != nil {
258→		return false
259→	}
260→
261→	lines := strings.Split(string(buf), "\n")
262→	for _, line := range lines {
263→		line = strings.TrimSpace(line)
264→		if line == "" || !strings.Contains(line, stopHookSentinel) {
265→			continue
266→		}
267→
268→		var entry struct {
269→			Timestamp string `json:"timestamp"`
270→		}
271→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
272→			continue
273→		}
274→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
275→		if err != nil {
276→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
277→			if err != nil {
278→				continue
279→			}
280→		}
281→		// Validate timestamp is within acceptable range:
282→		// - Not too far in the past (before hook started minus skew)
283→		// - Not too far in the future (after hook started plus skew)
284→		lowerBound := hookStartTime.Add(-maxSkew)
285→		upperBound := hookStartTime.Add(maxSkew)
286→		if ts.After(lowerBound) && ts.Before(upperBound) {
287→			return true
288→		}
289→	}
290→	return false
291→}
