 504→impl DeveloperInstructions {
 505→    pub fn new<T: Into<String>>(text: T) -> Self {
 506→        Self { text: text.into() }
 507→    }
 508→
 509→    pub fn from(
 510→        approval_policy: AskForApproval,
 511→        approvals_reviewer: ApprovalsReviewer,
 512→        exec_policy: &Policy,
 513→        exec_permission_approvals_enabled: bool,
 514→        request_permissions_tool_enabled: bool,
 515→    ) -> DeveloperInstructions {
 516→        let with_request_permissions_tool = |text: &str| {
 517→            if request_permissions_tool_enabled {
 518→                format!("{text}\n\n{}", request_permissions_tool_prompt_section())
 519→            } else {
 520→                text.to_string()
 521→            }
 522→        };
 523→        let on_request_instructions = || {
 524→            let on_request_rule = if exec_permission_approvals_enabled {
 525→                APPROVAL_POLICY_ON_REQUEST_RULE_REQUEST_PERMISSION.to_string()
 526→            } else {
 527→                APPROVAL_POLICY_ON_REQUEST_RULE.to_string()
 528→            };
 529→            let mut sections = vec![on_request_rule];
 530→            if request_permissions_tool_enabled {
 531→                sections.push(request_permissions_tool_prompt_section().to_string());
 532→            }
 533→            if let Some(prefixes) = approved_command_prefixes_text(exec_policy) {
 534→                sections.push(format!(
 535→                    "## Approved command prefixes\nThe following prefix rules have already been approved: {prefixes}"
 536→                ));
 537→            }
 538→            sections.join("\n\n")
 539→        };
 540→        let text = match approval_policy {
 541→            AskForApproval::Never => APPROVAL_POLICY_NEVER.to_string(),
 542→            AskForApproval::UnlessTrusted => {
 543→                with_request_permissions_tool(APPROVAL_POLICY_UNLESS_TRUSTED)
 544→            }
 545→            AskForApproval::OnFailure => with_request_permissions_tool(APPROVAL_POLICY_ON_FAILURE),
 546→            AskForApproval::OnRequest => on_request_instructions(),
 547→            AskForApproval::Granular(granular_config) => granular_instructions(
 548→                granular_config,
 549→                exec_policy,
 550→                exec_permission_approvals_enabled,
 551→                request_permissions_tool_enabled,
 552→            ),
 553→        };
 554→
 555→        let text = if approvals_reviewer == ApprovalsReviewer::GuardianSubagent
 556→            && approval_policy != AskForApproval::Never
 557→        {
 558→            format!("{text}\n\n{GUARDIAN_SUBAGENT_APPROVAL_SUFFIX}")
 559→        } else {
 560→            text
 561→        };
 562→
 563→        DeveloperInstructions::new(text)
 564→    }
