 566→    pub fn into_text(self) -> String {
 567→        self.text
 568→    }
 569→
 570→    pub fn concat(self, other: impl Into<DeveloperInstructions>) -> Self {
 571→        let mut text = self.text;
 572→        if !text.ends_with('\n') {
 573→            text.push('\n');
 574→        }
 575→        text.push_str(&other.into().text);
 576→        Self { text }
 577→    }
