 609→    pub fn from_policy(
 610→        sandbox_policy: &SandboxPolicy,
 611→        approval_policy: AskForApproval,
 612→        approvals_reviewer: ApprovalsReviewer,
 613→        exec_policy: &Policy,
 614→        cwd: &Path,
 615→        exec_permission_approvals_enabled: bool,
 616→        request_permissions_tool_enabled: bool,
 617→    ) -> Self {
 618→        let network_access = if sandbox_policy.has_full_network_access() {
 619→            NetworkAccess::Enabled
 620→        } else {
 621→            NetworkAccess::Restricted
 622→        };
 623→
 624→        let (sandbox_mode, writable_roots) = match sandbox_policy {
 625→            SandboxPolicy::DangerFullAccess => (SandboxMode::DangerFullAccess, None),
 626→            SandboxPolicy::ReadOnly { .. } => (SandboxMode::ReadOnly, None),
 627→            SandboxPolicy::ExternalSandbox { .. } => (SandboxMode::DangerFullAccess, None),
 628→            SandboxPolicy::WorkspaceWrite { .. } => {
 629→                let roots = sandbox_policy.get_writable_roots_with_cwd(cwd);
 630→                (SandboxMode::WorkspaceWrite, Some(roots))
 631→            }
 632→        };
 633→
 634→        DeveloperInstructions::from_permissions_with_network(
 635→            sandbox_mode,
 636→            network_access,
 637→            PermissionsPromptConfig {
 638→                approval_policy,
 639→                approvals_reviewer,
 640→                exec_policy,
 641→                exec_permission_approvals_enabled,
 642→                request_permissions_tool_enabled,
 643→            },
 644→            writable_roots,
 645→        )
 646→    }
