 661→
 662→    fn from_permissions_with_network(
 663→        sandbox_mode: SandboxMode,
 664→        network_access: NetworkAccess,
 665→        config: PermissionsPromptConfig<'_>,
 666→        writable_roots: Option<Vec<WritableRoot>>,
 667→    ) -> Self {
 668→        let start_tag = DeveloperInstructions::new("<permissions instructions>");
 669→        let end_tag = DeveloperInstructions::new("</permissions instructions>");
 670→        start_tag
 671→            .concat(DeveloperInstructions::sandbox_text(
 672→                sandbox_mode,
 673→                network_access,
 674→            ))
 675→            .concat(DeveloperInstructions::from(
 676→                config.approval_policy,
 677→                config.approvals_reviewer,
 678→                config.exec_policy,
 679→                config.exec_permission_approvals_enabled,
 680→                config.request_permissions_tool_enabled,
 681→            ))
 682→            .concat(DeveloperInstructions::from_writable_roots(writable_roots))
 683→            .concat(end_tag)
 684→    }
 685→
 686→    fn from_writable_roots(writable_roots: Option<Vec<WritableRoot>>) -> Self {
 687→        let Some(roots) = writable_roots else {
 688→            return DeveloperInstructions::new("");
 689→        };
 690→
 691→        if roots.is_empty() {
 692→            return DeveloperInstructions::new("");
 693→        }
 694→
 695→        let roots_list: Vec<String> = roots
 696→            .iter()
 697→            .map(|r| format!("`{}`", r.root.to_string_lossy()))
 698→            .collect();
 699→        let text = if roots_list.len() == 1 {
 700→            format!(" The writable root is {}.", roots_list[0])
 701→        } else {
 702→            format!(" The writable roots are {}.", roots_list.join(", "))
 703→        };
 704→        DeveloperInstructions::new(text)
 705→    }
 706→
 707→    fn sandbox_text(mode: SandboxMode, network_access: NetworkAccess) -> DeveloperInstructions {
 708→        let template = match mode {
 709→            SandboxMode::DangerFullAccess => SANDBOX_MODE_DANGER_FULL_ACCESS.trim_end(),
 710→            SandboxMode::WorkspaceWrite => SANDBOX_MODE_WORKSPACE_WRITE.trim_end(),
 711→            SandboxMode::ReadOnly => SANDBOX_MODE_READ_ONLY.trim_end(),
 712→        };
 713→        let text = template.replace("{network_access}", &network_access.to_string());
 714→
 715→        DeveloperInstructions::new(text)
 716→    }
 717→}
