 732→fn granular_instructions(
 733→    granular_config: GranularApprovalConfig,
 734→    exec_policy: &Policy,
 735→    exec_permission_approvals_enabled: bool,
 736→    request_permissions_tool_enabled: bool,
 737→) -> String {
 738→    let sandbox_approval_prompts_allowed = granular_config.allows_sandbox_approval();
 739→    let shell_permission_requests_available =
 740→        exec_permission_approvals_enabled && sandbox_approval_prompts_allowed;
 741→    let request_permissions_tool_prompts_allowed =
 742→        request_permissions_tool_enabled && granular_config.allows_request_permissions();
 743→    let categories = [
 744→        Some((
 745→            granular_config.allows_sandbox_approval(),
 746→            "`sandbox_approval`",
 747→        )),
 748→        Some((granular_config.allows_rules_approval(), "`rules`")),
 749→        Some((granular_config.allows_skill_approval(), "`skill_approval`")),
 750→        request_permissions_tool_enabled.then_some((
 751→            granular_config.allows_request_permissions(),
 752→            "`request_permissions`",
 753→        )),
 754→        Some((
 755→            granular_config.allows_mcp_elicitations(),
 756→            "`mcp_elicitations`",
 757→        )),
 758→    ];
 759→    let prompted_categories = categories
 760→        .iter()
 761→        .flatten()
 762→        .filter(|&&(is_allowed, _)| is_allowed)
 763→        .map(|&(_, category)| format!("- {category}"))
 764→        .collect::<Vec<_>>();
 765→    let rejected_categories = categories
 766→        .iter()
 767→        .flatten()
 768→        .filter(|&&(is_allowed, _)| !is_allowed)
 769→        .map(|&(_, category)| format!("- {category}"))
 770→        .collect::<Vec<_>>();
 771→
 772→    let mut sections = vec![granular_prompt_intro_text().to_string()];
 773→
 774→    if !prompted_categories.is_empty() {
 775→        sections.push(format!(
 776→            "These approval categories may still prompt the user when needed:\n{}",
 777→            prompted_categories.join("\n")
 778→        ));
 779→    }
 780→    if !rejected_categories.is_empty() {
 781→        sections.push(format!(
 782→            "These approval categories are automatically rejected instead of prompting the user:\n{}",
 783→            rejected_categories.join("\n")
 784→        ));
 785→    }
 786→
 787→    if shell_permission_requests_available {
 788→        sections.push(APPROVAL_POLICY_ON_REQUEST_RULE_REQUEST_PERMISSION.to_string());
 789→    }
 790→
 791→    if request_permissions_tool_prompts_allowed {
 792→        sections.push(request_permissions_tool_prompt_section().to_string());
 793→    }
 794→
 795→    if let Some(prefixes) = approved_command_prefixes_text(exec_policy) {
 796→        sections.push(format!(
 797→            "## Approved command prefixes\nThe following prefix rules have already been approved: {prefixes}"
 798→        ));
 799→    }
 800→
 801→    sections.join("\n\n")
 802→}
 803→
 804→const MAX_RENDERED_PREFIXES: usize = 100;
 805→const MAX_ALLOW_PREFIX_TEXT_BYTES: usize = 5000;
 806→const TRUNCATED_MARKER: &str = "...\n[Some commands were truncated]";
 807→
 808→pub fn format_allow_prefixes(prefixes: Vec<Vec<String>>) -> Option<String> {
 809→    let mut truncated = false;
 810→    if prefixes.len() > MAX_RENDERED_PREFIXES {
 811→        truncated = true;
 812→    }
 813→
 814→    let mut prefixes = prefixes;
 815→    prefixes.sort_by(|a, b| {
 816→        a.len()
 817→            .cmp(&b.len())
 818→            .then_with(|| prefix_combined_str_len(a).cmp(&prefix_combined_str_len(b)))
 819→            .then_with(|| a.cmp(b))
 820→    });
 821→
 822→    let full_text = prefixes
 823→        .into_iter()
 824→        .take(MAX_RENDERED_PREFIXES)
 825→        .map(|prefix| format!("- {}", render_command_prefix(&prefix)))
 826→        .collect::<Vec<_>>()
 827→        .join("\n");
 828→
 829→    // truncate to last UTF8 char
 830→    let mut output = full_text;
 831→    let byte_idx = output
 832→        .char_indices()
 833→        .nth(MAX_ALLOW_PREFIX_TEXT_BYTES)
 834→        .map(|(i, _)| i);
 835→    if let Some(byte_idx) = byte_idx {
 836→        truncated = true;
 837→        output = output[..byte_idx].to_string();
 838→    }
 839→
 840→    if truncated {
 841→        Some(format!("{output}{TRUNCATED_MARKER}"))
 842→    } else {
 843→        Some(output)
 844→    }
 845→}
 846→
 847→fn prefix_combined_str_len(prefix: &[String]) -> usize {
 848→    prefix.iter().map(String::len).sum()
 849→}
 850→
 851→fn render_command_prefix(prefix: &[String]) -> String {
 852→    let tokens = prefix
 853→        .iter()
 854→        .map(|token| serde_json::to_string(token).unwrap_or_else(|_| format!("{token:?}")))
 855→        .collect::<Vec<_>>()
 856→        .join(", ");
 857→    format!("[{tokens}]")
 858→}
