 972→pub fn local_image_content_items_with_label_number(
 973→    path: &std::path::Path,
 974→    file_bytes: Vec<u8>,
 975→    label_number: Option<usize>,
 976→    mode: PromptImageMode,
 977→) -> Vec<ContentItem> {
 978→    match load_for_prompt_bytes(path, file_bytes, mode) {
 979→        Ok(image) => {
 980→            let mut items = Vec::with_capacity(3);
 981→            if let Some(label_number) = label_number {
 982→                items.push(ContentItem::InputText {
 983→                    text: local_image_open_tag_text(label_number),
 984→                });
 985→            }
 986→            items.push(ContentItem::InputImage {
 987→                image_url: image.into_data_url(),
 988→            });
 989→            if label_number.is_some() {
 990→                items.push(ContentItem::InputText {
 991→                    text: LOCAL_IMAGE_CLOSE_TAG.to_string(),
 992→                });
 993→            }
 994→            items
 995→        }
 996→        Err(err) => match &err {
 997→            ImageProcessingError::Read { .. } | ImageProcessingError::Encode { .. } => {
 998→                vec![local_image_error_placeholder(path, &err)]
 999→            }
1000→            ImageProcessingError::Decode { .. } if err.is_invalid_image() => {
1001→                vec![invalid_image_error_placeholder(path, &err)]
1002→            }
1003→            ImageProcessingError::Decode { .. } => {
1004→                vec![local_image_error_placeholder(path, &err)]
1005→            }
1006→            ImageProcessingError::UnsupportedImageFormat { mime } => {
1007→                vec![unsupported_image_error_placeholder(path, mime)]
1008→            }
1009→        },
1010→    }
1011→}
