1243→/// example telemetry previews or legacy string-only output paths) while keeping
1244→/// the original multimodal `content_items` as the authoritative payload sent to
1245→/// the model.
1246→pub fn function_call_output_content_items_to_text(
1247→    content_items: &[FunctionCallOutputContentItem],
1248→) -> Option<String> {
1249→    let text_segments = content_items
1250→        .iter()
1251→        .filter_map(|item| match item {
1252→            FunctionCallOutputContentItem::InputText { text } if !text.trim().is_empty() => {
1253→                Some(text.as_str())
1254→            }
1255→            FunctionCallOutputContentItem::InputText { .. }
1256→            | FunctionCallOutputContentItem::InputImage { .. } => None,
1257→        })
1258→        .collect::<Vec<_>>();
1259→
1260→    if text_segments.is_empty() {
1261→        None
1262→    } else {
1263→        Some(text_segments.join("\n"))
1264→    }
1265→}
