1267→impl From<crate::dynamic_tools::DynamicToolCallOutputContentItem>
1268→    for FunctionCallOutputContentItem
1269→{
1270→    fn from(item: crate::dynamic_tools::DynamicToolCallOutputContentItem) -> Self {
1271→        match item {
1272→            crate::dynamic_tools::DynamicToolCallOutputContentItem::InputText { text } => {
1273→                Self::InputText { text }
1274→            }
1275→            crate::dynamic_tools::DynamicToolCallOutputContentItem::InputImage { image_url } => {
1276→                Self::InputImage {
1277→                    image_url,
1278→                    detail: None,
1279→                }
1280→            }
1281→        }
1282→    }
1283→}
