139→// CalculateTokenUsage calculates token usage from a Claude Code transcript.
140→// This is specific to Claude/Anthropic's API format where each assistant message
141→// contains a usage object with input_tokens, output_tokens, and cache tokens.
142→//
143→// Due to streaming, multiple transcript rows may share the same message.id.
144→// We deduplicate by taking the row with the highest output_tokens for each message.id.
145→func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
146→	// Map from message.id to the usage with highest output_tokens
147→	usageByMessageID := make(map[string]messageUsage)
148→
149→	for _, line := range transcript {
150→		if line.Type != "assistant" {
151→			continue
152→		}
153→
154→		var msg messageWithUsage
155→		if err := json.Unmarshal(line.Message, &msg); err != nil {
156→			continue
157→		}
158→
159→		if msg.ID == "" {
160→			continue
161→		}
162→
163→		// Keep the entry with highest output_tokens (final streaming state)
164→		existing, exists := usageByMessageID[msg.ID]
165→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
166→			usageByMessageID[msg.ID] = msg.Usage
167→		}
168→	}
169→
170→	// Sum up all unique messages
171→	usage := &agent.TokenUsage{
172→		APICallCount: len(usageByMessageID),
173→	}
174→	for _, u := range usageByMessageID {
175→		usage.InputTokens += u.InputTokens
176→		usage.CacheCreationTokens += u.CacheCreationInputTokens
177→		usage.CacheReadTokens += u.CacheReadInputTokens
178→		usage.OutputTokens += u.OutputTokens
179→	}
180→
181→	return usage
182→}
183→
184→// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
185→// If startLine > 0, only considers lines from startLine onwards.
186→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
187→	if path == "" {
188→		return &agent.TokenUsage{}, nil
189→	}
190→
191→	lines, err := transcript.ParseFromFileAtLine(path, startLine)
192→	if err != nil {
193→		return nil, err //nolint:wrapcheck // caller adds context
194→	}
195→
196→	return CalculateTokenUsage(lines), nil
197→}
198→
199→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
200→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
201→// Returns a map of agentID -> toolUseID for all spawned agents.
202→func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
203→	agentIDs := make(map[string]string)
204→
205→	for _, line := range transcript {
206→		if line.Type != "user" {
207→			continue
208→		}
209→
210→		// Parse as array of content blocks (tool results)
211→		var contentBlocks []struct {
212→			Type      string          `json:"type"`
213→			ToolUseID string          `json:"tool_use_id"`
214→			Content   json.RawMessage `json:"content"`
215→		}
216→
217→		var msg struct {
218→			Content json.RawMessage `json:"content"`
219→		}
220→		if err := json.Unmarshal(line.Message, &msg); err != nil {
221→			continue
222→		}
223→
224→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
225→			continue
226→		}
227→
228→		for _, block := range contentBlocks {
229→			if block.Type != "tool_result" {
230→				continue
231→			}
232→
233→			// Content can be a string or array of text blocks
234→			var textContent string
235→
236→			// Try as array of text blocks first
237→			var textBlocks []struct {
238→				Type string `json:"type"`
239→				Text string `json:"text"`
240→			}
241→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
242→				var textContentSb361 strings.Builder
243→				for _, tb := range textBlocks {
244→					if tb.Type == "text" {
245→						textContentSb361.WriteString(tb.Text + "\n")
246→					}
247→				}
248→				textContent += textContentSb361.String()
249→			} else {
250→				// Try as plain string
251→				var str string
252→				if err := json.Unmarshal(block.Content, &str); err == nil {
253→					textContent = str
254→				}
255→			}
256→
257→			// Look for agentId in the text
258→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
259→				agentIDs[agentID] = block.ToolUseID
260→			}
261→		}
262→	}
263→
264→	return agentIDs
265→}
266→
267→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
268→func extractAgentIDFromText(text string) string {
269→	const prefix = "agentId: "
270→	idx := strings.Index(text, prefix)
271→	if idx == -1 {
272→		return ""
273→	}
274→
275→	// Extract the ID (alphanumeric characters after the prefix)
276→	start := idx + len(prefix)
277→	end := start
278→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
279→		text[end] >= 'A' && text[end] <= 'Z' ||
280→		text[end] >= '0' && text[end] <= '9') {
281→		end++
282→	}
283→
284→	if end > start {
285→		return text[start:end]
286→	}
287→	return ""
288→}
